RAW={
'shoulder':[
[('상완이두근 장두건병증·건초염','어깨 앞쪽을 지나는 장두건 자체 또는 그 주위 건초에 변화가 생긴 상태입니다.','어깨 앞 통증;팔을 들거나 물건을 옮길 때 통증;이두근 고랑 부위 압통','건의 섬유·두께와 건초를 함께 봅니다. 건초액만으로 건초염을 단정하지 않습니다.','biceps'),('장두건 아탈구·탈구','장두건이 이두근 고랑에서 부분적으로 또는 완전히 벗어나는 상태입니다.','어깨 앞 통증;회전할 때 걸림·튕김;동반 회전근개 손상 시 근력 저하','팔을 회전시키며 건의 경로와 견갑하근건을 확인합니다.','shoulder')],
[('견갑하근건 파열','팔을 안으로 돌리는 회전근개 힘줄의 섬유가 일부 또는 전층에서 끊어진 상태입니다.','어깨 앞 통증;등 뒤로 손을 보내기 어려움;내회전 동작의 힘 저하','두 직교면의 결손과 장두건 안정성을 함께 봅니다.','shoulder'),('석회성 건병증','회전근개 힘줄에 칼슘 결정이 침착되는 상태로, 석회가 있어도 증상이 없을 수 있습니다.','어깨 통증;급성기 심한 야간통;통증에 따른 운동 제한','고에코 석회와 음향음영·점액낭 반응을 확인합니다.','shoulder')],
[('극상근건 파열','팔을 들어 올리는 데 기여하는 극상근건이 부분적으로 또는 전층으로 끊어진 상태입니다.','팔을 들 때 통증;옆으로 누울 때 통증;들어 올리는 힘 저하','장축·단축으로 결손을 재확인합니다. 이방성에 의한 저에코와 구분합니다.','shoulder'),('회전근개 건병증','회전근개 힘줄에 부하와 관련된 통증·기능 저하 및 구조 변화가 생긴 상태입니다.','팔을 반복해서 사용할 때 통증;어깨 바깥쪽 통증;운동 후 불편감','비후와 에코 변화가 증상 부위와 일치하는지 확인합니다.','shoulder')],
[('견봉하–삼각근하 점액낭염','회전근개와 견봉·삼각근 사이의 마찰을 줄이는 점액낭에 염증·팽창이 생긴 상태입니다.','팔을 들 때 통증;어깨 외측 압통;아픈 쪽으로 누울 때 통증','점액낭의 액체·벽·혈류와 동반 회전근개 병변을 확인합니다.','shoulder'),('견봉하 통증·견봉쇄골관절 병변','팔을 들 때의 견봉하 통증과 어깨 위 관절의 퇴행성 변화는 서로 다른 통증 원인이 될 수 있습니다.','중간 범위에서 팔을 들 때 통증;어깨 꼭대기 통증;팔을 몸 반대편으로 모을 때 통증','통증 위치와 동적 소견을 구분합니다. 영상의 골극만으로 통증 원인을 확정하지 않습니다.','shoulder')],
[('후방 관절 삼출','관절 뒤쪽 오목에 관절액이 증가한 소견입니다. 하나의 특정 질환명이 아닙니다.','뻣뻣함;깊은 관절통;원인에 따른 운동 제한','액체를 찾은 뒤 염증·외상 등 원인을 임상적으로 구분합니다.','shoulder'),('관절와순 주위 낭종·극하근 위축','관절와순 주변 낭종은 신경을 압박할 수 있고, 극하근 위축은 신경·건 문제 등에서 생길 수 있습니다.','어깨 뒤 통증;외회전 근력 저하;근육의 윤곽 감소','낭종·근육 크기 변화를 확인하되 깊은 관절와순 전체는 초음파만으로 평가하기 어렵습니다.','shoulder')]],
'elbow':[
[('원위 이두근건병증·파열','팔꿈치 앞에서 요골에 붙는 이두근건이 손상된 상태입니다.','팔꿈치 앞 통증;손바닥을 위로 돌리는 힘 저하;파열 시 멍·갑작스러운 통증','비스듬한 부착부의 이방성을 보정하고 건의 연속성을 따라갑니다.','elbowAll'),('팔꿈치 관절 삼출·유리체','관절액 증가 또는 관절 안에서 떨어져 나온 연골·뼛조각이 있는 상태입니다.','붓고 뻣뻣함;굽힘·폄 제한;유리체가 끼면 걸림·잠김','관절 오목을 관찰합니다. 잠김의 모든 원인이 초음파로 보이는 것은 아닙니다.','elbowAll')],
[('내측상과 건병증 · 골프엘보','손목 굴근·회내근의 공통 부착부에 생기는 부하 관련 건병증입니다.','팔꿈치 안쪽 통증;손목을 굽히거나 쥘 때 통증;내측상과 압통','총굴근건을 보며 척골신경 증상과 인대 손상도 구분합니다.','golfer'),('척측측부인대 손상','팔꿈치가 바깥으로 벌어지는 힘에 저항하는 내측 인대가 손상된 상태입니다.','투구 시 안쪽 통증;불안정감;급성 손상 때 붓기','인대의 연속성과 증상을 확인합니다. 과도한 스트레스 검사를 피합니다.','elbow')],
[('외측상과 건병증 · 테니스엘보','손목 신전근의 공통 부착부에 반복 부하로 통증과 건 변화가 생긴 상태입니다.','팔꿈치 바깥 통증;쥐거나 손목을 펼 때 통증;악력 저하','총신근건의 구조와 통증 재현을 연결합니다.','tennis'),('요골두 주변 관절·인대 손상','요골두와 주변 관절 구조가 외상 등으로 손상된 상태입니다.','팔꿈치 바깥 통증;전완 회전 제한;외상 후 붓기','골절·불안정성은 진찰 및 필요한 추가 영상과 함께 평가합니다.','elbowAll')],
[('주두 점액낭염','팔꿈치 끝의 피부와 주두 사이 점액낭이 자극·염증으로 팽창한 상태입니다.','팔꿈치 끝의 볼록한 붓기;압박 시 통증;감염 시 열감·발적','관절액과 점액낭액의 위치를 구분합니다. 발열·심한 발적은 감염 평가가 필요합니다.','bursa'),('삼두근건병증·손상','팔꿈치를 펴는 삼두근건의 부착부에 병변이 생긴 상태입니다.','팔꿈치 뒤 통증;밀기·펴기 동작 통증;큰 파열 시 신전력 저하','주두 부착부와 건의 연속성을 관찰합니다.','elbowAll')],
[('주관증후군 · 척골신경병증','팔꿈치 부근 척골신경이 압박·자극을 받아 기능 이상이 생긴 상태입니다.','새끼손가락·약지 척측 저림;팔꿈치를 오래 굽히면 악화;진행 시 손 근력 저하','신경 구조·크기·주변 압박 원인을 확인합니다. 크기 하나로 확진하지 않습니다.','cubital'),('척골신경 아탈구·튕김삼두근','굴곡 시 척골신경이나 삼두근 일부가 내측상과를 넘어 이동하는 현상입니다.','팔꿈치 안쪽의 튕김;동작 시 불편감;신경 자극이 있으면 저림','움직임 자체는 무증상일 수 있습니다. 신경과 근육을 따로 추적합니다.','elbow')]],
'hand_wrist':[
[('손목터널증후군','수근관 안의 정중신경이 압박되어 손 감각·기능에 이상이 생기는 질환입니다.','엄지·검지·중지 및 약지 요측 저림;야간 증상;진행 시 엄지두덩 근력 저하','신경과 굴근건초를 함께 확인합니다. 초음파 단면적만으로 진단하지 않습니다.','cts'),('굴근건초염','손목·손가락 굴근건을 둘러싼 건초의 염증성 변화입니다.','움직일 때 통증;건 경로를 따른 부종;때로 뻣뻣함·걸림','건초액과 활막·혈류를 구분하고 임상 원인을 확인합니다.','wrist')],
[('드퀘르벵 건초염','손목 요측의 제1 신전건 구획에서 엄지 힘줄의 활주가 어려워지는 상태입니다.','엄지 쪽 손목 통증;엄지를 쓰거나 물건을 들 때 통증;요골경상돌기 주변 압통','장무지외전근·단무지신근과 구획 중격·지대를 확인합니다.','wrist'),('교차증후군','손목 신전건 구획이 교차하는 부근의 마찰·건초 자극으로 생기는 상태입니다.','손등쪽 전완 통증;반복 손목 운동 때 악화;때로 마찰감·부종','통증 위치를 따라 교차점을 확인해 드퀘르벵 병변과 구분합니다.','wrist')],
[('방아쇠수지','굴근건이 A1 활차 부근을 원활하게 통과하지 못해 걸리는 상태입니다.','손가락 굽힘·폄 때 딸깍거림;손바닥쪽 손가락 밑 통증;아침 뻣뻣함·잠김','A1 활차와 굴근건 활주를 동적으로 확인합니다.','finger'),('손바닥판 손상','손가락 관절의 과신전을 막는 손바닥쪽 구조가 손상된 상태입니다.','접질린 뒤 관절 손바닥쪽 통증;붓기;관절 불안정감','박리 골편과 판의 연속성을 보되 골절 평가는 추가 영상이 필요할 수 있습니다.','finger')],
[('활막염·염증성 관절병증','관절 안쪽 활막에 염증이 생기는 상태로 류마티스관절염 등 여러 원인이 있습니다.','관절 통증·붓기;아침 뻣뻣함;여러 관절이 함께 불편할 수 있음','활막 비후·혈류·미란은 임상·혈액검사와 연결해 해석합니다.','finger'),('시상대 손상','손허리손가락관절 등쪽에서 신전건을 잡아 주는 지지 구조가 손상된 상태입니다.','손등 관절 통증·붓기;주먹을 쥘 때 건이 옆으로 이동;손가락을 펴기 어려움','정적 영상과 굽힘·폄에서 신전건 이동을 함께 확인합니다.','finger')],
[('삼각섬유연골복합체 · TFCC 병변','손목 척측의 하중 전달·안정화 구조에 생기는 외상성 또는 퇴행성 병변입니다.','새끼손가락 쪽 손목 통증;비틀거나 짚을 때 통증;딸깍거림','초음파에서 보이는 범위가 제한적입니다. 정상 영상만으로 배제하지 않습니다.','wrist'),('척측수근신근건 · ECU 병변','척측 손목 신전건 또는 이를 고정하는 구조의 건병증·불안정성입니다.','손목 척측 등쪽 통증;회전 시 튕김;운동 중 불편감','ECU의 건초와 전완 회전에 따른 경로를 관찰합니다.','wrist')]],
'knee':[
[('무릎 관절 삼출·활막염','무릎 관절액이 증가하거나 활막에 염증이 생긴 상태입니다.','붓기;굽힐 때 뻣뻣함;원인에 따른 통증·열감','슬개상 오목에서 액체와 활막을 구분합니다. 발열·심한 열감은 감염 감별이 우선입니다.','knee'),('대퇴사두근건병증·파열','슬개골 위에 붙는 무릎 신전건의 병변입니다.','슬개골 위 통증;무릎 펴기 통증;큰 파열 시 다리를 능동적으로 들기 어려움','부착부와 섬유 연속성을 확인합니다. 신전기전 기능 소실은 신속한 평가가 필요합니다.','knee')],
[('슬개건병증','슬개골과 경골을 잇는 힘줄의 부하 관련 통증·기능 저하입니다.','슬개골 아래 통증;점프·달리기·계단에서 악화;국소 압통','건의 변화와 통증 부위를 대응시킵니다. 영상 이상이 항상 통증을 뜻하지 않습니다.','knee'),('오스굿–슐라터병 의심·호파 지방체 자극','성장기 경골조면의 견인성 병변과 슬개건 뒤 지방체의 자극은 서로 다른 전방 무릎 통증 원인입니다.','경골조면 돌출·압통;달리기·점프 시 통증;지방체 자극 시 슬개건 주변 통증','통증이 건·조면·지방체 중 어디에 있는지 구분합니다.','knee')],
[('내측측부인대 · MCL 손상','무릎 안쪽 안정성을 유지하는 인대의 손상입니다.','무릎 안쪽 통증;외상 후 국소 붓기;불안정감','섬유 손상 위치와 주변 구조를 확인합니다.','knee'),('내측 반월상연골 병변·거위발 점액낭염','관절선의 반월상연골 문제와 그보다 아래쪽 거위발 건 주변 점액낭 염증은 통증 위치가 다릅니다.','관절선 통증·걸림;거위발 부위 압통;계단이나 보행 시 통증','주변부 반월상연골·점액낭을 구분합니다. 깊은 연골 파열 전체는 초음파로 배제할 수 없습니다.','knee')],
[('장경인대 관련 외측 무릎 통증','장경인대와 외측 대퇴골 주변 연부조직의 반복 부하와 관련된 통증입니다.','달리기 중 외측 무릎 통증;반복 굽힘·폄에서 악화;국소 압통','통증 지점의 인대·주변 조직을 확인하고 관절선 병변과 구분합니다.','knee'),('외측측부인대 · LCL 손상','무릎 바깥쪽 대퇴골과 비골을 잇는 안정화 인대의 손상입니다.','외측 무릎 통증;외상 후 붓기;불안정감','다른 후외측 구조와 동반 손상이 있을 수 있습니다.','knee')],
[('베이커낭종','반막양근과 내측 비복근 사이 점액낭이 액체로 팽창한 상태로 관절 내 병변과 동반될 수 있습니다.','무릎 뒤 종괴·당김;굽힘 제한;작으면 무증상','목과 관절 연결을 확인합니다. 갑작스러운 종아리 부종은 혈전증 등도 감별해야 합니다.','baker'),('후방십자인대 병변·슬와 혈관 변화','깊은 후방 인대 병변과 혈관 이상은 서로 다른 원인입니다.','외상 뒤 불안정감;뒤쪽 통증;혈관 문제에서는 부종·박동성 종괴 등이 가능','후방 MSK 영상만으로 인대 전체나 혈관 질환을 배제하지 않습니다.','knee')]],
'hip':[
[('고관절 삼출·활막염','고관절 관절액 증가 또는 활막 염증으로 전방 관절 오목이 팽창한 상태입니다.','서혜부 통증;관절 움직임 제한;절뚝거림','액체는 원인을 뜻하지 않습니다. 발열·체중부하 불가 등은 신속한 임상 평가가 필요합니다.','hip'),('대퇴비구 충돌·관절와순 병변','대퇴골–비구의 형태와 움직임에 관련된 충돌 또는 비구 가장자리 연골 구조의 병변입니다.','깊은 서혜부 통증;앉기·굽힘·회전에서 통증;걸림감','초음파로 전체 관절와순·충돌 원인을 확진하거나 배제하지 않습니다.','hip')],
[('장요근 건·점액낭 병변 및 내측 탄발고관절','장요근 건의 자극, 주변 점액낭 팽창 또는 움직임 중 건의 튕김 현상입니다.','앞쪽 고관절·서혜부 통증;다리를 움직일 때 튕김;고관절 굽힘 통증','증상과 동적 건 이동을 함께 관찰합니다.','hip'),('대퇴직근 기시부 손상','골반 앞에서 시작하는 대퇴직근의 건·근육이 손상된 상태입니다.','차기·달리기 후 앞쪽 통증;고관절 굽힘·무릎 펴기 통증;급성기 멍','기시부와 근건 이행부를 확인하고 성장기 박리 손상 가능성도 고려합니다.','hip')],
[('대전자 통증 증후군 · GTPS','고관절 바깥쪽 통증을 보이는 증후군으로 둔근건병증·파열과 점액낭 병변 등을 포함합니다.','옆으로 누울 때 통증;계단·한발 지지 시 통증;대전자 압통','점액낭액만 찾지 말고 중둔근·소둔근 부착부를 함께 봅니다.','hip'),('중둔근·소둔근건 파열','골반을 지지하고 다리를 벌리는 둔근 힘줄의 섬유 손상입니다.','외측 고관절 통증;외전 근력 저하;보행 시 골반 지지 불안정','건의 부착면·결손·근육 상태를 연결해 관찰합니다.','hip')],
[('내전근건병증·근육 파열','허벅지 안쪽 근육·힘줄이 반복 부하 또는 갑작스러운 신장에 의해 손상된 상태입니다.','서혜부·허벅지 안쪽 통증;다리를 모을 때 통증;급성 파열 시 멍','치골 부착부에서 근육까지 따라가며 결손·혈종을 확인합니다.','adductor'),('서혜부 통증의 다른 원인','서혜부 통증은 고관절·치골·서혜관·신경 등 여러 구조에서 생길 수 있는 증상입니다.','뛰거나 방향 전환 시 통증;일부에서 기침·힘주기 시 통증;감각 변화','통증 위치만으로 스포츠 탈장·폐쇄신경병증을 확정하지 않습니다.','hip')],
[('근위 햄스트링건병증·파열','좌골결절에 붙는 햄스트링 기시부의 병변입니다.','앉을 때 엉덩이 아래 통증;달리기·몸 숙이기 시 통증;급성기 멍','부착부 건·근건부·후퇴·혈종을 확인합니다.','hip'),('깊은 둔부 증후군·좌골대퇴 충돌 의심','깊은 둔부의 신경 자극 또는 좁아진 좌골–대퇴 공간과 관련된 통증 상태입니다.','둔부 깊은 통증;다리 뒤쪽으로 퍼지는 증상;특정 자세에서 악화','요추 등 다른 원인을 감별하며 초음파 단일 수치로 확진하지 않습니다.','hip')]],
'ankle':[
[('전방 발목 관절 삼출·충돌','관절액 증가 또는 발목 앞 연부조직·뼈의 충돌과 관련된 병변입니다.','발목 앞 통증;발등을 당길 때 걸림;붓기','전방 관절 오목과 골피질을 보며 증상·외상 기전과 연결합니다.','ankle'),('전방 건초염','전경골근·발가락 신전건 등의 건초에 생기는 염증성 변화입니다.','발목 앞·발등 통증;힘줄 경로를 따른 부종;발목·발가락 운동 통증','건초·건 자체·도플러 혈류를 나누어 관찰합니다.','ankle')],
[('외측 발목 인대 손상 · ATFL/CFL','주로 발목을 안쪽으로 접질리며 외측 인대가 늘어나거나 끊어진 상태입니다.','외과 앞·아래 통증;멍·붓기;반복 접질림·불안정감','인대별 경로와 연속성을 확인하고 골절·동반 손상을 고려합니다.','ankle'),('비골근건병증·건초염·불안정성','외과 뒤를 지나는 비골근건이나 지지 구조의 병변입니다.','외과 뒤 통증;발을 바깥으로 밀 때 통증;회전 시 튕김','건의 분할 파열과 동적 위치 변화를 관찰합니다.','ankle')],
[('후경골근건병증·삼각인대 손상','발목 내측 힘줄의 부하 관련 병변과 내측 안정화 인대의 외상성 손상은 구분해야 합니다.','내과 주변 통증;보행·발뒤꿈치 들기 시 통증;인대 손상 후 붓기','힘줄·인대를 각각 따라가며 통증 위치와 기능을 연결합니다.','ankle'),('족근관증후군 의심','내과 뒤 족근관 부위에서 경골신경 또는 가지가 압박·자극되는 상태입니다.','발바닥의 화끈거림·저림;서 있거나 걸을 때 악화;내과 뒤 불편감','주변 종괴·건초액 등을 확인하지만 정상 초음파로 신경병증을 배제하지 않습니다.','ankle')],
[('아킬레스건병증','아킬레스건의 부하 관련 통증·기능 저하로 부착부 또는 중간부에 생길 수 있습니다.','아침 뻣뻣함;달리기·발뒤꿈치 들기 시 통증;건의 압통','부착부와 중간부를 나눠 건·건주위·점액낭을 확인합니다.','achilles'),('후종골 점액낭염·아킬레스건 파열','종골 앞 점액낭의 염증과 아킬레스건의 섬유 단절은 서로 다른 병변입니다.','뒤꿈치 뒤 통증;신발 압박 시 통증;파열 시 갑작스러운 통증과 밀어내기 약화','급성 기능 저하는 신속한 평가가 필요합니다. 건의 연속성과 점액낭을 구분합니다.','ankle')],
[('족저근막병증 · 족저근막염','발바닥 아치를 지지하는 근막, 특히 종골 부착부에 통증과 구조 변화가 생긴 상태입니다.','아침 첫발 통증;오래 앉았다 일어날 때 통증;뒤꿈치 발바닥쪽 압통','측정 위치·에코·증상을 함께 보며 두께 하나로 확진하지 않습니다.','plantar'),('족저근막 파열','족저근막의 섬유가 부분적으로 또는 완전히 끊어진 상태입니다.','갑작스러운 발바닥 통증;멍·붓기;체중부하 시 통증','두 직교면에서 섬유 결손을 확인합니다. 종골 골극만으로 통증 원인을 설명하지 않습니다.','plantar')]]}
DISEASES={key:[{'conditions':[dict(zip(['name','definition','symptoms','link','source'],c)) for c in row]} for row in rows] for key,rows in RAW.items()}
